EMBEDDED_BASE_HTML = ''

EMBEDDED_DASHBOARD_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Adroit AI - Multi-Consultant US IT Staffing & ATS Platform</title>\n    <link rel="stylesheet" href="/static/css/style.css">\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Outfit:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap" rel="stylesheet">\n</head>\n<body>\n    <div class="app-container">\n        <!-- Sidebar Navigation -->\n        <aside class="sidebar">\n            <div class="brand-wrapper">\n                <div class="brand-icon">A</div>\n                <div class="brand-text">\n                    <h2>Adroit ATS</h2>\n                    <span>US IT Staffing & Bench Hub</span>\n                </div>\n            </div>\n\n            <!-- Active Consultant Selector Card -->\n            <div class="active-consultant-card">\n                <div class="active-label">ACTIVE CONSULTANT</div>\n                <select id="global-active-consultant" class="consultant-dropdown">\n                    {% for c in candidates %}\n                    <option value="{{ c.id }}" {% if loop.first %}selected{% endif %}>\n                        {{ c.name }} ({{ c.title }})\n                    </option>\n                    {% endfor %}\n                </select>\n                <div id="active-consultant-badges" class="consultant-sub-badges">\n                    <span id="active-gmail-badge" class="mini-badge">Checking Gmail...</span>\n                    <span id="active-rate-badge" class="mini-badge rate-tag">$90/hr C2C</span>\n                </div>\n            </div>\n\n            <nav class="nav-menu">\n                <div class="nav-section-title">BENCH MARKETING & JOBS</div>\n                <a href="#jobs" class="nav-item active" data-tab="jobs">\n                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>\n                    <span>24h USA IT Jobs Feed</span>\n                    <span class="nav-badge live-badge">LIVE 24h</span>\n                </a>\n                <a href="#students" class="nav-item" data-tab="students">\n                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 10v6M2 10l10-5 10 5-10 5z"/><path d="M6 12v5c3 3 9 3 12 0v-5"/></svg>\n                    <span>US Bench Sourcing (2018–2026)</span>\n                    <span class="badge-hot" style="background:linear-gradient(135deg, #8b5cf6, #d946ef); color:white; font-size:10px; padding:2px 6px; border-radius:10px; margin-left:auto; font-weight:700; box-shadow:0 2px 5px rgba(139,92,246,0.3);">HOTLIST</span>\n                </a>\n                <a href="#consultants" class="nav-item" data-tab="consultants">\n                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M23 21v-2a4 4 0 0 0-3-3.87"></path><path d="M16 3.13a4 4 0 0 1 0 7.75"></path></svg>\n                    <span>US Bench Consultants</span>\n                    <span class="nav-badge count-badge">{{ candidates|length }}</span>\n                </a>\n                <a href="#drafts" class="nav-item" data-tab="drafts">\n                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"></path><polyline points="22,6 12,13 2,6"></polyline></svg>\n                    <span>Gmail Drafts & Pipeline</span>\n                    <span class="nav-badge draft-badge" id="sidebar-draft-count">DRAFTS</span>\n                </a>\n                <div class="nav-section-title">AI SUPERPOWERS</div>\n                <a href="#resumebot" class="nav-item" data-tab="resumebot">\n                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line><polyline points="10 9 9 9 8 9"></polyline></svg>\n                    <span>Master Resume Bot</span>\n                    <span class="nav-badge docx-badge">.DOCX</span>\n                </a>\n            </nav>\n\n            <div class="sidebar-footer">\n                <div class="user-profile-card">\n                    <img src="{{ user.avatar_url or \'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&auto=format&fit=crop&q=80\' }}" alt="{{ user.name }}" class="avatar">\n                    <div class="user-info">\n                        <div class="name">{{ user.name }}</div>\n                        <div class="role">{{ user.role }}</div>\n                    </div>\n                    <a href="/logout" class="logout-btn" title="Sign Out">\n                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"></path><polyline points="16 17 21 12 16 7"></polyline><line x1="21" y1="12" x2="9" y2="12"></line></svg>\n                    </a>\n                </div>\n            </div>\n        </aside>\n\n        <!-- Main Content Area -->\n        <div class="main-wrapper">\n            <!-- Top Header -->\n            <header class="top-header">\n                <div class="header-search">\n                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>\n                    <input type="text" id="quick-job-filter-input" placeholder="Quick filter live jobs by skill (Python, Java, AWS, DevOps, React)...">\n                </div>\n\n                <div class="header-actions">\n                    <button class="btn btn-success btn-sm" id="btn-open-paste-draft-modal" style="box-shadow: 0 0 15px rgba(16, 185, 129, 0.4);">\n                        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><rect x="8" y="2" width="8" height="4" rx="1" ry="1"></rect></svg>\n                        📋 Paste Requirement & Draft\n                    </button>\n                    <button class="btn btn-secondary btn-sm" id="btn-open-add-consultant">\n                        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>\n                        Add Consultant\n                    </button>\n                    <button class="btn btn-primary btn-sm" id="btn-header-scrape-us">\n                        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M23 4v6h-6"></path><path d="M1 20v-6h6"></path><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"></path></svg>\n                        Scrape 24h US Jobs\n                    </button>\n                </div>\n            </header>\n\n            <!-- Dynamic Tab Panes -->\n            <main class="content-area">\n\n                <!-- TAB 1: 24-HOUR USA IT JOBS TABLE & OUTREACH -->\n                <div class="tab-pane active" id="tab-jobs">\n                    <div class="section-header">\n                        <div>\n                            <h2>Live 24-Hour USA IT Jobs & 1-Click Outreach</h2>\n                            <p>Scraped fresh C2C contract requisitions across LinkedIn US, Dice.com, Indeed, ZipRecruiter & CareerBuilder. Edit recruiter emails directly in the table and create 1-click Gmail drafts with attached .docx resumes.</p>\n                        </div>\n                        <div class="stats-pills">\n                            <span class="pill"><strong id="stat-total-jobs">{{ stats.total_jobs }}</strong> Total Jobs</span>\n                            <span class="pill pill-green"><strong id="stat-email-jobs">{{ stats.jobs_with_email }}</strong> Direct Emails</span>\n                            <span class="pill pill-purple"><strong id="stat-drafted-count">{{ stats.drafted_count }}</strong> Drafts Created</span>\n                        </div>\n                    </div>\n\n                    <!-- Search and Filter Bar -->\n                    <div class="filter-card">\n                        <div class="filter-row">\n                            <div class="filter-group">\n                                <label>Search Role / Skills</label>\n                                <input type="text" id="filter-query" placeholder="e.g. AI Automation, Java Spring Boot, DevOps..." value="AI Automation">\n                            </div>\n                            <div class="filter-group">\n                                <label>US Location</label>\n                                <input type="text" id="filter-location" placeholder="United States, Dallas TX, Remote..." value="United States">\n                            </div>\n                            <div class="filter-group">\n                                <label>Portal Source</label>\n                                <select id="filter-source">\n                                    <option value="All">All US Portals (LinkedIn, Dice, Indeed, Zip, CB)</option>\n                                    <option value="LinkedIn">LinkedIn (Live 24h)</option>\n                                    <option value="Dice">Dice.com</option>\n                                    <option value="Indeed">Indeed USA</option>\n                                    <option value="ZipRecruiter">ZipRecruiter</option>\n                                    <option value="CareerBuilder">CareerBuilder</option>\n                                </select>\n                            </div>\n                            <div class="filter-group filter-actions">\n                                <label>&nbsp;</label>\n                                <button class="btn btn-primary" id="btn-search-jobs">\n                                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>\n                                    Search Jobs\n                                </button>\n                                <button class="btn btn-success" id="btn-live-scrape-trigger">\n                                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M23 4v6h-6"></path><path d="M1 20v-6h6"></path><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"></path></svg>\n                                    Live 24h Scrape\n                                </button>\n                            </div>\n                        </div>\n                    </div>\n\n                    <!-- Interactive Live Jobs Table -->\n                    <div class="jobs-table-wrap">\n                        <div class="table-header-info">\n                            <span id="jobs-table-count">Showing Live US Requisitions</span>\n                            <span class="table-tip">💡 Tip: Type or paste recruiter email directly into the cell — it auto-saves instantly!</span>\n                        </div>\n                        <table class="data-table" id="jobs-data-table">\n                            <thead>\n                                <tr>\n                                    <th style="width: 28%;">Job Title & Company</th>\n                                    <th style="width: 12%;">Portal</th>\n                                    <th style="width: 14%;">Rate / Type</th>\n                                    <th style="width: 22%;">Recruiter Email (In-Table Edit)</th>\n                                    <th style="width: 12%;">Target Consultant</th>\n                                    <th style="width: 12%; text-align: right;">1-Click Actions</th>\n                                </tr>\n                            </thead>\n                            <tbody id="jobs-table-body">\n                                <tr>\n                                    <td colspan="6" class="loading-cell">\n                                        <div class="spinner"></div> Loading fresh 24h US contract jobs...\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n\n                <!-- TAB 2: US BENCH CONSULTANTS HUB -->\n                \n                <!-- TAB 5: US BENCH SOURCING & STUDENTS (2018 - 2026) -->\n                <div class="tab-pane" id="tab-students">\n                    <div class="view-header" style="margin-bottom: 24px;">\n                        <div class="view-title">\n                            <h2>🎓 US Bench Candidates & Student Sourcing (2018–2026)</h2>\n                            <p>Automated LinkedIn Sourcing of Indian Master\'s Graduates, OPT/CPT Holders, and US Tech Job Switchers</p>\n                        </div>\n                        <div class="view-actions" style="display:flex; gap:12px; align-items:center; flex-wrap:wrap;">\n                            <button id="btn-open-live-linkedin" class="btn btn-secondary" style="display:flex; align-items:center; gap:8px; background: rgba(14, 118, 168, 0.25); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.4);">\n                                <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M19 3a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h14m-.5 15.5v-5.3a3.26 3.26 0 0 0-3.26-3.26c-.85 0-1.84.52-2.28 1.3v-1.11h-2.79v8.37h2.79v-4.93c0-.77.62-1.4 1.39-1.4a1.4 1.4 0 0 1 1.4 1.4v4.93h2.75M6.46 10.9v8.37H9.2V10.9H6.46M7.83 6.27a1.6 1.6 0 1 0 0 3.2 1.6 1.6 0 0 0 0-3.2Z"/></svg>\n                                🌐 Open Live LinkedIn Search\n                            </button>\n                            <button id="btn-export-students-csv" class="btn btn-secondary" style="display:flex; align-items:center; gap:8px;">\n                                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>\n                                Export to Excel (.CSV)\n                            </button>\n                            <button id="btn-trigger-students-scrape" class="btn btn-primary" style="display:flex; align-items:center; gap:8px; background:linear-gradient(135deg, #8b5cf6, #6366f1); border:none; box-shadow:0 4px 14px rgba(99,102,241,0.4);">\n                                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M23 4v6h-6"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>\n                                ⚡ Run LinkedIn Scrape\n                            </button>\n                        </div>\n                    </div>\n\n                    <!-- Metrics Ribbon -->\n                    <div class="stats-grid" style="grid-template-columns: repeat(4, 1fr); margin-bottom: 24px;">\n                        <div class="stat-card" style="border-left: 4px solid #8b5cf6;">\n                            <div class="stat-icon" style="background: rgba(139, 92, 246, 0.15); color: #8b5cf6;">🎓</div>\n                            <div class="stat-info">\n                                <div class="stat-label">CANDIDATES FOUND</div>\n                                <div class="stat-value" id="stat-students-count">0</div>\n                                <div class="stat-desc">Targeted 2018–2026 Cohort</div>\n                            </div>\n                        </div>\n                        <div class="stat-card" style="border-left: 4px solid #10b981;">\n                            <div class="stat-icon" style="background: rgba(16, 185, 129, 0.15); color: #10b981;">🔥</div>\n                            <div class="stat-info">\n                                <div class="stat-label">RECENT OPT / CPT GRADS</div>\n                                <div class="stat-value" id="stat-students-opt">0</div>\n                                <div class="stat-desc">2024–2026 Passouts (Ready)</div>\n                            </div>\n                        </div>\n                        <div class="stat-card" style="border-left: 4px solid #3b82f6;">\n                            <div class="stat-icon" style="background: rgba(59, 130, 246, 0.15); color: #3b82f6;">⚡</div>\n                            <div class="stat-info">\n                                <div class="stat-label">JOB SWITCHERS</div>\n                                <div class="stat-value" id="stat-students-switchers">0</div>\n                                <div class="stat-desc">2018–2023 US Exp (Immediate)</div>\n                            </div>\n                        </div>\n                        <div class="stat-card" style="border-left: 4px solid #f59e0b;">\n                            <div class="stat-icon" style="background: rgba(245, 158, 11, 0.15); color: #f59e0b;">💼</div>\n                            <div class="stat-info">\n                                <div class="stat-label">BENCH ONBOARDED</div>\n                                <div class="stat-value" id="stat-students-onboarded">0</div>\n                                <div class="stat-desc">Active in ATS Hotlist</div>\n                            </div>\n                        </div>\n                    </div>\n\n                    <!-- Search & Filter Controls -->\n                    <!-- MyMulya Style Filter & Search Control Bar -->\n                    <div class="filter-panel" style="background: var(--bg-card, #1e2230); border: 1px solid var(--border-color, #2d3348); border-radius: 14px; padding: 22px; margin-bottom: 24px; box-shadow: 0 4px 16px rgba(0,0,0,0.2);">\n                        <form id="form-student-search" onsubmit="return false;">\n                            <div style="display: grid; grid-template-columns: 2.5fr 1fr 1fr 1.5fr 1.2fr; gap: 14px; align-items: flex-end;">\n                                <!-- Technology / Major / Keywords -->\n                                <div>\n                                    <label style="display:block; font-size:12px; font-weight:700; color:#94a3b8; margin-bottom:6px; text-transform:uppercase; letter-spacing:0.5px;">\n                                        Technology / Major / Keywords\n                                    </label>\n                                    <div style="position:relative;">\n                                        <span style="position:absolute; left:12px; top:11px; color:#64748b; font-size:14px;">🔍</span>\n                                        <input type="text" id="filter-student-keyword" class="form-control" placeholder="e.g. Computer Science, Java, Python, AWS, Data Science" value="Computer Science" style="width:100%; height:42px; background:var(--bg-main, #141722); color:#fff; border:1px solid var(--border-color, #2d3348); border-radius:8px; padding-left:36px; padding-right:12px; font-size:13px;" />\n                                    </div>\n                                </div>\n\n                                <!-- From Year -->\n                                <div>\n                                    <label style="display:block; font-size:12px; font-weight:700; color:#94a3b8; margin-bottom:6px; text-transform:uppercase; letter-spacing:0.5px;">\n                                        From Year\n                                    </label>\n                                    <select id="filter-student-from-year" class="form-control" style="width:100%; height:42px; background:var(--bg-main, #141722); color:#fff; border:1px solid var(--border-color, #2d3348); border-radius:8px; padding:0 10px; font-size:13px;">\n                                        <option value="2018" selected>2018</option>\n                                        <option value="2019">2019</option>\n                                        <option value="2020">2020</option>\n                                        <option value="2021">2021</option>\n                                        <option value="2022">2022</option>\n                                        <option value="2023">2023</option>\n                                        <option value="2024">2024</option>\n                                        <option value="2025">2025</option>\n                                        <option value="2026">2026</option>\n                                    </select>\n                                </div>\n\n                                <!-- To Year -->\n                                <div>\n                                    <label style="display:block; font-size:12px; font-weight:700; color:#94a3b8; margin-bottom:6px; text-transform:uppercase; letter-spacing:0.5px;">\n                                        To Year\n                                    </label>\n                                    <select id="filter-student-to-year" class="form-control" style="width:100%; height:42px; background:var(--bg-main, #141722); color:#fff; border:1px solid var(--border-color, #2d3348); border-radius:8px; padding:0 10px; font-size:13px;">\n                                        <option value="2026" selected>2026</option>\n                                        <option value="2025">2025</option>\n                                        <option value="2024">2024</option>\n                                        <option value="2023">2023</option>\n                                        <option value="2022">2022</option>\n                                        <option value="2021">2021</option>\n                                        <option value="2020">2020</option>\n                                        <option value="2019">2019</option>\n                                        <option value="2018">2018</option>\n                                    </select>\n                                </div>\n\n                                <!-- Target Location -->\n                                <div>\n                                    <label style="display:block; font-size:12px; font-weight:700; color:#94a3b8; margin-bottom:6px; text-transform:uppercase; letter-spacing:0.5px;">\n                                        Target Location\n                                    </label>\n                                    <input type="text" id="filter-student-location" class="form-control" value="United States" placeholder="e.g. United States, Texas, California" style="width:100%; height:42px; background:var(--bg-main, #141722); color:#fff; border:1px solid var(--border-color, #2d3348); border-radius:8px; padding:0 12px; font-size:13px;" />\n                                </div>\n\n                                <!-- Search Button -->\n                                <div>\n                                    <button type="button" id="btn-apply-student-filter" class="btn btn-primary" style="width:100%; height:42px; font-weight:700; font-size:13px; display:flex; align-items:center; justify-content:center; gap:8px; background:linear-gradient(135deg, #4f46e5 0%, #4338ca 100%); border:none; box-shadow:0 3px 10px rgba(79, 70, 229, 0.3);">\n                                        <span>🔍 Search</span>\n                                    </button>\n                                </div>\n                            </div>\n\n                            <!-- Quick Preset Filter Chips (MyMulya Style) -->\n                            <div style="display:flex; gap:8px; margin-top:16px; align-items:center; flex-wrap:wrap;">\n                                <span style="font-size:11px; font-weight:700; color:#64748b; text-transform:uppercase;">Quick Presets:</span>\n                                <button type="button" onclick="setPresetFilter(\'all\', 2018, 2026)" class="btn-preset active" style="font-size:11px; padding:4px 10px; border-radius:16px; background:rgba(99,102,241,0.2); color:#a5b4fc; border:1px solid rgba(99,102,241,0.4); cursor:pointer; font-weight:600;">\n                                    🎓 All Years (2018–2026)\n                                </button>\n                                <button type="button" onclick="setPresetFilter(\'all\', 2024, 2026)" class="btn-preset" style="font-size:11px; padding:4px 10px; border-radius:16px; background:rgba(16,185,129,0.15); color:#6ee7b7; border:1px solid rgba(16,185,129,0.3); cursor:pointer; font-weight:600;">\n                                    🔥 Fresh Grads (2024–2026 OPT/CPT)\n                                </button>\n                                <button type="button" onclick="setPresetFilter(\'all\', 2018, 2023)" class="btn-preset" style="font-size:11px; padding:4px 10px; border-radius:16px; background:rgba(59,130,246,0.15); color:#93c5fd; border:1px solid rgba(59,130,246,0.3); cursor:pointer; font-weight:600;">\n                                    ⚡ Job Switchers (2018–2023 Exp)\n                                </button>\n                                <button type="button" onclick="setPresetFilter(\'Java Developer\', 2018, 2026)" class="btn-preset" style="font-size:11px; padding:4px 10px; border-radius:16px; background:rgba(255,255,255,0.06); color:#e2e8f0; border:1px solid rgba(255,255,255,0.1); cursor:pointer; font-weight:600;">\n                                    ☕ Java / Full Stack\n                                </button>\n                                <button type="button" onclick="setPresetFilter(\'Data Science\', 2018, 2026)" class="btn-preset" style="font-size:11px; padding:4px 10px; border-radius:16px; background:rgba(255,255,255,0.06); color:#e2e8f0; border:1px solid rgba(255,255,255,0.1); cursor:pointer; font-weight:600;">\n                                    📊 Data & AI/ML\n                                </button>\n                                <button type="button" onclick="setPresetFilter(\'DevOps AWS\', 2018, 2026)" class="btn-preset" style="font-size:11px; padding:4px 10px; border-radius:16px; background:rgba(255,255,255,0.06); color:#e2e8f0; border:1px solid rgba(255,255,255,0.1); cursor:pointer; font-weight:600;">\n                                    ☁️ Cloud / DevOps\n                                </button>\n                            </div>\n                        </form>\n                    </div>\n\n                    <!-- Candidates Results Table (Row Layout) -->\n                    <div id="students-results-wrapper">\n                        <div class="table-container" style="background: var(--bg-card, #1e2230); border: 1px solid var(--border-color, #2d3348); border-radius: 12px; overflow-x: auto; box-shadow: 0 4px 20px rgba(0,0,0,0.25);">\n                            <table class="data-table" id="students-table" style="width: 100%; border-collapse: collapse; text-align: left; min-width: 980px;">\n                                <thead>\n                                    <tr style="background: rgba(255,255,255,0.03); border-bottom: 1px solid var(--border-color, #2d3348);">\n                                        <th style="padding: 14px 16px; font-size: 12px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px;">Candidate Name</th>\n                                        <th style="padding: 14px 16px; font-size: 12px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px;">Degree & Background</th>\n                                        <th style="padding: 14px 16px; font-size: 12px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px; text-align:center;">Grad Year</th>\n                                        <th style="padding: 14px 16px; font-size: 12px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px;">University</th>\n                                        <th style="padding: 14px 16px; font-size: 12px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px;">US Location</th>\n                                        <th style="padding: 14px 16px; font-size: 12px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px;">Status / Intent</th>\n                                        <th style="padding: 14px 16px; font-size: 12px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px;">LinkedIn Profile</th>\n                                        <th style="padding: 14px 16px; font-size: 12px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px; text-align: right;">Quick Actions</th>\n                                    </tr>\n                                </thead>\n                                <tbody id="students-table-body">\n                                    <!-- Candidate rows loaded dynamically via app.js -->\n                                </tbody>\n                            </table>\n                        </div>\n                        <div id="students-loading-state" style="display: none; text-align: center; padding: 60px 20px;">\n                            <div class="spinner" style="margin: 0 auto 16px;"></div>\n                            <h3 style="color: #fff; margin-bottom: 8px;">Scraping LinkedIn Profiles...</h3>\n                            <p style="color: #8e95aa;">Scanning public X-Ray index for 2018–2026 US Master\'s students & job switchers</p>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- OUTREACH PITCH MODAL -->\n                <div id="modal-student-pitch" class="modal-overlay" style="display:none; position:fixed; top:0; left:0; right:0; bottom:0; background:rgba(0,0,0,0.75); z-index:9999; display:none; align-items:center; justify-content:center;">\n                    <div class="modal-box" style="background:#1e2230; border:1px solid #2d3348; border-radius:14px; width:650px; max-width:95vw; padding:28px; box-shadow:0 20px 50px rgba(0,0,0,0.6);">\n                        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:20px;">\n                            <h3 style="margin:0; color:#fff; display:flex; align-items:center; gap:8px;">\n                                <span>✉️</span> Bench Placement Outreach Pitch\n                            </h3>\n                            <button id="btn-close-pitch-modal" style="background:transparent; border:none; color:#8e95aa; font-size:24px; cursor:pointer;">&times;</button>\n                        </div>\n                        <div style="margin-bottom:16px;">\n                            <label style="display:block; font-size:12px; font-weight:600; color:#8e95aa; margin-bottom:6px;">SUBJECT</label>\n                            <input type="text" id="pitch-modal-subject" class="form-control" style="width:100%; height:40px; background:#141722; color:#fff; border:1px solid #2d3348; border-radius:8px; padding:0 12px;" />\n                        </div>\n                        <div style="margin-bottom:20px;">\n                            <label style="display:block; font-size:12px; font-weight:600; color:#8e95aa; margin-bottom:6px;">EMAIL / INMAIL BODY</label>\n                            <textarea id="pitch-modal-body" rows="10" class="form-control" style="width:100%; background:#141722; color:#fff; border:1px solid #2d3348; border-radius:8px; padding:12px; font-family:inherit; font-size:13px; line-height:1.5;"></textarea>\n                        </div>\n                        <div style="display:flex; justify-content:flex-end; gap:12px;">\n                            <button id="btn-copy-pitch" class="btn btn-secondary">📋 Copy to Clipboard</button>\n                            <button id="btn-close-pitch" class="btn btn-primary">Done</button>\n                        </div>\n                    </div>\n                </div>\n\n<div class="tab-pane" id="tab-consultants">\n                    <div class="section-header">\n                        <div>\n                            <h2>US IT Bench Consultants Hub</h2>\n                            <p>Manage your active consultant profiles, upload .docx Master Resumes, and connect individual consultant Gmail accounts for 1-click automated outreach drafting.</p>\n                        </div>\n                        <button class="btn btn-primary" id="btn-add-consultant-tab">\n                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>\n                            Add New Consultant Profile\n                        </button>\n                    </div>\n\n                    <div class="consultants-grid" id="consultants-cards-container">\n                        <!-- Rendered dynamically by JavaScript -->\n                    </div>\n                </div>\n\n                <!-- TAB 3: GMAIL DRAFTS & OUTREACH PIPELINE -->\n                <div class="tab-pane" id="tab-drafts">\n                    <div class="section-header">\n                        <div>\n                            <h2>Gmail Drafts & Application Pipeline</h2>\n                            <p>Track all drafted and submitted applications across all consultant Gmail accounts. Review draft timestamps, recruiter contacts, and target roles.</p>\n                        </div>\n                    </div>\n\n                    <div class="pipeline-kanban" id="pipeline-container">\n                        <div class="pipeline-column">\n                            <div class="column-header">\n                                <span class="col-title">Drafted in Gmail</span>\n                                <span class="col-count" id="count-Drafted">0</span>\n                            </div>\n                            <div class="column-cards" id="col-Drafted"></div>\n                        </div>\n                        <div class="pipeline-column">\n                            <div class="column-header">\n                                <span class="col-title">Applied / Submitted</span>\n                                <span class="col-count" id="count-Applied">0</span>\n                            </div>\n                            <div class="column-cards" id="col-Applied"></div>\n                        </div>\n                        <div class="pipeline-column">\n                            <div class="column-header">\n                                <span class="col-title">Interviewing</span>\n                                <span class="col-count" id="count-Interviewing">0</span>\n                            </div>\n                            <div class="column-cards" id="col-Interviewing"></div>\n                        </div>\n                        <div class="pipeline-column">\n                            <div class="column-header">\n                                <span class="col-title">Offer / Placed</span>\n                                <span class="col-count" id="count-Offer">0</span>\n                            </div>\n                            <div class="column-cards" id="col-Offer"></div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- TAB 4: MASTER RESUME BOT STUDIO -->\n                <div class="tab-pane" id="tab-resumebot">\n                    <div class="section-header">\n                        <div>\n                            <h2>AI Master Resume Optimization Bot</h2>\n                            <p>Align candidate resumes with client JDs following the strict ATS Keyword & Domain Optimization Rules. Generates ready-to-submit Word (.docx) resumes with tailored highlights.</p>\n                        </div>\n                    </div>\n\n                    <div class="resume-studio-grid">\n                        <div class="studio-card">\n                            <h3 class="card-title">1. Select Consultant & Base Resume</h3>\n                            <div class="form-group">\n                                <label>Bench Consultant</label>\n                                <select id="resumebot-consultant-select" class="form-control">\n                                    {% for c in candidates %}\n                                    <option value="{{ c.id }}" {% if loop.first %}selected{% endif %}>{{ c.name }} - {{ c.title }}</option>\n                                    {% endfor %}\n                                </select>\n                            </div>\n                            <div class="form-group">\n                                <label>Or Upload New .docx / .pdf Resume</label>\n                                <input type="file" id="resumebot-file-input" accept=".docx,.pdf,.txt" class="form-control">\n                            </div>\n                            <div class="form-group">\n                                <label>Consultant Resume Text (Auto-Populated)</label>\n                                <textarea id="resumebot-resume-text" rows="10" class="form-control" placeholder="Resume text will populate here..."></textarea>\n                            </div>\n                        </div>\n\n                        <div class="studio-card">\n                            <h3 class="card-title">2. Target Job Description (JD)</h3>\n                            <div class="form-group">\n                                <label>Paste Client Requisition / JD</label>\n                                <textarea id="resumebot-jd-text" rows="8" class="form-control" placeholder="Paste full client job description here..."></textarea>\n                            </div>\n                            <div class="form-group">\n                                <label>Custom Optimization Instructions (Optional)</label>\n                                <input type="text" id="resumebot-custom-notes" class="form-control" placeholder="e.g. Emphasize AWS EKS and Kafka event streaming">\n                            </div>\n                            <button class="btn btn-primary btn-block" id="btn-run-resume-optimization">\n                                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"></polygon></svg>\n                                ⚡ Optimize & Calculate Match %\n                            </button>\n                        </div>\n                    </div>\n\n                    <!-- Optimization Results Section -->\n                    <div id="resumebot-results-card" class="results-card" style="display: none; margin-top: 24px;">\n                        <div class="result-header">\n                            <div>\n                                <h3 id="result-title">Resume Optimization Complete</h3>\n                                <span id="result-domain" class="badge badge-domain">Fintech / Banking</span>\n                            </div>\n                            <button class="btn btn-success" id="btn-download-optimized-docx">\n                                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg>\n                                Download Tailored .DOCX Resume\n                            </button>\n                        </div>\n\n                        <div class="match-score-bar-wrap">\n                            <div class="score-labels">\n                                <span>Initial ATS Match: <strong id="score-initial">65%</strong></span>\n                                <span>Optimized ATS Match: <strong id="score-target" style="color: #34d399;">95%</strong></span>\n                            </div>\n                            <div class="progress-track">\n                                <div class="progress-fill" id="score-progress-bar" style="width: 95%;"></div>\n                            </div>\n                        </div>\n\n                        <div class="skills-matched-grid">\n                            <div class="skill-box">\n                                <h4>✅ Matched Core Keywords</h4>\n                                <div id="result-matched-skills" class="tags-container"></div>\n                            </div>\n                            <div class="skill-box">\n                                <h4>➕ Strategic Keywords Added</h4>\n                                <div id="result-added-skills" class="tags-container"></div>\n                            </div>\n                        </div>\n\n                        <div class="form-group" style="margin-top: 16px;">\n                            <label>Optimized Resume Preview</label>\n                            <textarea id="result-preview-text" rows="12" class="form-control" readonly></textarea>\n                        </div>\n                    </div>\n                </div>\n\n            </main>\n        </div>\n    </div>\n\n    <!-- MODAL: ADD / EDIT CONSULTANT -->\n    <div class="modal-backdrop" id="modal-consultant" style="display: none;">\n        <div class="modal-dialog">\n            <div class="modal-header">\n                <h3 id="modal-consultant-title">Add New US Bench Consultant</h3>\n                <button class="modal-close" id="btn-close-consultant-modal">&times;</button>\n            </div>\n            <form id="form-consultant" enctype="multipart/form-data">\n                <input type="hidden" id="consultant-edit-id" value="">\n                <div class="modal-body">\n                    <div class="form-row">\n                        <div class="form-group">\n                            <label>Full Name *</label>\n                            <input type="text" id="c-name" name="name" class="form-control" required placeholder="e.g. Valipireddy Praveen">\n                        </div>\n                        <div class="form-group">\n                            <label>Email Address *</label>\n                            <input type="email" id="c-email" name="email" class="form-control" required placeholder="e.g. praveen@gmail.com">\n                        </div>\n                    </div>\n                    <div class="form-row">\n                        <div class="form-group">\n                            <label>Phone Number</label>\n                            <input type="text" id="c-phone" name="phone" class="form-control" placeholder="e.g. +1 (555) 382-9912">\n                        </div>\n                        <div class="form-group">\n                            <label>Professional Title *</label>\n                            <input type="text" id="c-title" name="title" class="form-control" required placeholder="e.g. Principal AI & Cloud Architect">\n                        </div>\n                    </div>\n                    <div class="form-group">\n                        <label>Primary Technical Skills (Comma-Separated) *</label>\n                        <input type="text" id="c-skills" name="skills" class="form-control" required placeholder="e.g. Python, AI Automation, LangChain, Spring Boot, AWS, Docker">\n                    </div>\n                    <div class="form-row">\n                        <div class="form-group">\n                            <label>Total Experience (Years)</label>\n                            <input type="number" id="c-exp" name="experience" class="form-control" value="8">\n                        </div>\n                        <div class="form-group">\n                            <label>Target Rate ($/hr C2C) *</label>\n                            <input type="text" id="c-rate" name="rate" class="form-control" value="$90/hr (C2C)" placeholder="$90/hr (C2C)">\n                        </div>\n                        <div class="form-group">\n                            <label>Visa Status *</label>\n                            <select id="c-visa" name="visa_status" class="form-control">\n                                <option value="US Citizen / C2C Eligible">US Citizen / C2C Eligible</option>\n                                <option value="Green Card (C2C)">Green Card (C2C)</option>\n                                <option value="H1B (Transfer/C2C)">H1B (Transfer/C2C)</option>\n                                <option value="OPT/CPT">OPT/CPT</option>\n                                <option value="C2C Eligible">C2C Eligible</option>\n                            </select>\n                        </div>\n                    </div>\n                    <div class="form-group">\n                        <label>Location / Relocation</label>\n                        <input type="text" id="c-location" name="location" class="form-control" value="Dallas, TX (Hybrid/Remote)">\n                    </div>\n                    <div class="form-group">\n                        <label>Upload Consultant Resume (.docx / .pdf)</label>\n                        <input type="file" id="c-resume-file" name="resume_file" accept=".docx,.pdf" class="form-control">\n                        <small class="form-hint">Upload the master Word (.docx) resume to automatically attach to 1-click Gmail drafts.</small>\n                    </div>\n                    <div class="form-group">\n                        <label>Executive Profile Summary</label>\n                        <textarea id="c-summary" name="summary" rows="3" class="form-control" placeholder="Summary highlights for client pitches..."></textarea>\n                    </div>\n                </div>\n                <div class="modal-footer">\n                    <button type="button" class="btn btn-secondary" id="btn-cancel-consultant">Cancel</button>\n                    <button type="submit" class="btn btn-primary" id="btn-save-consultant">Save Consultant</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- MODAL: UPLOAD RESUME ONLY -->\n    <div class="modal-backdrop" id="modal-upload-resume" style="display: none;">\n        <div class="modal-dialog modal-sm">\n            <div class="modal-header">\n                <h3>Upload Resume (.docx)</h3>\n                <button class="modal-close" id="btn-close-upload-modal">&times;</button>\n            </div>\n            <form id="form-upload-resume-only">\n                <input type="hidden" id="upload-candidate-id" value="">\n                <div class="modal-body">\n                    <p id="upload-candidate-name-label" style="font-size: 0.9rem; margin-bottom: 12px; color: var(--text-muted);"></p>\n                    <div class="form-group">\n                        <label>Select Word (.docx) or PDF File</label>\n                        <input type="file" id="quick-resume-file" accept=".docx,.pdf" class="form-control" required>\n                    </div>\n                </div>\n                <div class="modal-footer">\n                    <button type="button" class="btn btn-secondary" id="btn-cancel-upload">Cancel</button>\n                    <button type="submit" class="btn btn-primary" id="btn-submit-upload-resume">Upload & Attach</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n        <!-- MODAL: GMAIL APP PASSWORD SETUP -->\n    <div class="modal-backdrop" id="modal-app-password" style="display: none;">\n        <div class="modal-dialog modal-sm">\n            <div class="modal-header">\n                <h3>Connect Gmail (App Password)</h3>\n                <button class="modal-close" id="btn-close-app-pass-modal">&times;</button>\n            </div>\n            <form id="form-app-password">\n                <input type="hidden" id="app-pass-cand-id" value="">\n                <div class="modal-body">\n                    <p style="font-size: 0.8rem; color: var(--text-muted); margin-bottom: 14px;">\n                        Connect <strong id="app-pass-cand-name" style="color: #fff;"></strong>\'s Gmail without Google Cloud Console!\n                    </p>\n                    <div class="form-group">\n                        <label>Gmail Address *</label>\n                        <input type="email" id="app-pass-email" class="form-control" placeholder="e.g. karun.aiengineer@gmail.com" required>\n                    </div>\n                    <div class="form-group">\n                        <label>Google App Password (16 Characters) *</label>\n                        <input type="password" id="app-pass-key" class="form-control" placeholder="xxxx xxxx xxxx xxxx" required>\n                        <small class="form-hint">\n                            👉 Generate in 30s: <a href="https://myaccount.google.com/apppasswords" target="_blank" style="color: #60a5fa; text-decoration: underline;">myaccount.google.com/apppasswords</a> (Requires 2-Step Verification)\n                        </small>\n                    </div>\n                </div>\n                <div class="modal-footer">\n                    <button type="button" class="btn btn-secondary" id="btn-cancel-app-pass">Cancel</button>\n                    <button type="submit" class="btn btn-primary" id="btn-submit-app-pass">Verify & Connect</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n        <!-- MODAL: INSTANT REQUIREMENT PASTE & DRAFT -->\n    <div class="modal-backdrop" id="modal-paste-draft" style="display: none;">\n        <div class="modal-dialog">\n            <div class="modal-header">\n                <h3>📋 Paste Requirement ➔ 1-Click Gmail Draft</h3>\n                <button class="modal-close" id="btn-close-paste-draft-modal">&times;</button>\n            </div>\n            <form id="form-paste-draft">\n                <div class="modal-body">\n                    <div class="form-group">\n                        <label>Select Consultant to Submit *</label>\n                        <select id="pd-consultant-select" class="form-control" required>\n                            <!-- Populated dynamically -->\n                        </select>\n                    </div>\n\n                    <div class="form-group">\n                        <label>Paste Raw Requirement / Client Email / LinkedIn Message *</label>\n                        <textarea id="pd-raw-text" rows="7" class="form-control" placeholder="Paste the requirement here... The AI will instantly auto-detect the Recruiter Email, Job Title, Company, and Pay Rate!" required></textarea>\n                        <small class="form-hint" style="color: #34d399;">💡 Auto-extracts recruiter email & details in real-time as you paste.</small>\n                    </div>\n\n                    <div class="form-row">\n                        <div class="form-group">\n                            <label>Recruiter Email *</label>\n                            <input type="email" id="pd-email" class="form-control" placeholder="recruiter@client.com" required>\n                        </div>\n                        <div class="form-group">\n                            <label>Job Title *</label>\n                            <input type="text" id="pd-title" class="form-control" placeholder="e.g. Senior Java Cloud Engineer" required>\n                        </div>\n                    </div>\n\n                    <div class="form-row">\n                        <div class="form-group">\n                            <label>Client / Vendor Company</label>\n                            <input type="text" id="pd-company" class="form-control" placeholder="e.g. Apex Fintech">\n                        </div>\n                        <div class="form-group">\n                            <label>Pay Rate (C2C / Hourly)</label>\n                            <input type="text" id="pd-rate" class="form-control" placeholder="$90/hr (C2C)">\n                        </div>\n                    </div>\n\n                    <div class="form-group">\n                        <label>Custom Notes for Pitch (Optional)</label>\n                        <input type="text" id="pd-notes" class="form-control" placeholder="e.g. Emphasize AWS Microservices & Immediate Availability">\n                    </div>\n                </div>\n                <div class="modal-footer">\n                    <button type="button" class="btn btn-secondary" id="btn-cancel-paste-draft">Cancel</button>\n                    <button type="submit" class="btn btn-success" id="btn-submit-paste-draft" style="box-shadow: 0 0 15px rgba(16, 185, 129, 0.4);">\n                        ⚡ Create Gmail Draft (Attached .docx)\n                    </button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- TOAST NOTIFICATION CONTAINER -->\n    <div id="toast-container" class="toast-container"></div>\n\n    <script src="/static/js/app.js?v=2.6.0"></script>\n</body>\n</html>\n'

EMBEDDED_LOGIN_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Adroit AI - Sourcing & Resume Bot Studio</title>\n    <link rel="stylesheet" href="/static/css/style.css">\n    <style>\n        .login-wrapper {\n            min-height: 100vh;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            padding: 24px;\n            background-image: \n                radial-gradient(at 0% 0%, rgba(99, 102, 241, 0.2) 0px, transparent 50%),\n                radial-gradient(at 100% 100%, rgba(6, 182, 212, 0.15) 0px, transparent 50%);\n        }\n        .login-card {\n            background: rgba(15, 23, 42, 0.85);\n            backdrop-filter: blur(16px);\n            border: 1px solid rgba(255, 255, 255, 0.1);\n            border-radius: var(--radius-lg);\n            width: 100%;\n            max-width: 440px;\n            padding: 40px;\n            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.5), 0 0 30px rgba(99, 102, 241, 0.2);\n            text-align: center;\n        }\n        .login-logo {\n            width: 54px;\n            height: 54px;\n            background: linear-gradient(135deg, var(--primary), var(--accent-cyan));\n            border-radius: 14px;\n            margin: 0 auto 20px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-size: 1.75rem;\n            font-weight: 800;\n            color: white;\n            box-shadow: 0 0 20px rgba(99, 102, 241, 0.5);\n        }\n        .auth-divider {\n            display: flex;\n            align-items: center;\n            margin: 24px 0;\n            color: var(--text-muted);\n            font-size: 0.75rem;\n            text-transform: uppercase;\n            letter-spacing: 0.05em;\n        }\n        .auth-divider::before, .auth-divider::after {\n            content: \'\';\n            flex: 1;\n            height: 1px;\n            background: var(--border-subtle);\n        }\n        .auth-divider span {\n            padding: 0 12px;\n        }\n        .feature-badge {\n            display: inline-flex;\n            align-items: center;\n            gap: 6px;\n            padding: 4px 12px;\n            background: rgba(99, 102, 241, 0.15);\n            border: 1px solid rgba(99, 102, 241, 0.3);\n            border-radius: var(--radius-full);\n            color: #a5b4fc;\n            font-size: 0.75rem;\n            font-weight: 600;\n            margin-bottom: 16px;\n        }\n    </style>\n</head>\n<body>\n    <div class="login-wrapper">\n        <div class="login-card">\n            <div class="login-logo">A</div>\n            <div class="feature-badge">\n                <span>⚡</span> AI Sourcing & Resume Alignment Studio\n            </div>\n            <h1 style="font-size: 1.75rem; margin-bottom: 8px;">Adroit AI Studio</h1>\n            <p style="color: var(--text-secondary); font-size: 0.9rem; margin-bottom: 28px;">\n                24-Hour Live Contract Job Scraping (LinkedIn / Indeed / Dice) & Master Resume Alignment.\n            </p>\n\n            <!-- 1-Click Test Login -->\n            <a href="/dev-login" class="btn-primary" style="width: 100%; justify-content: center; padding: 14px; font-size: 1rem; margin-bottom: 12px; border-radius: var(--radius-md);">\n                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>\n                Launch Studio (1-Click Recruiter Access)\n            </a>\n            <div style="font-size: 0.775rem; color: var(--text-muted); margin-bottom: 8px;">\n                Instant session as <strong>Praveen Valipireddy</strong> (Lead Recruiter)\n            </div>\n\n            <div class="auth-divider">\n                <span>or Enterprise Single Sign-On</span>\n            </div>\n\n            <!-- Microsoft 365 SSO Login -->\n            <a href="/auth/azure" class="btn-secondary" style="width: 100%; justify-content: center; padding: 12px; font-size: 0.9rem; border-radius: var(--radius-md);">\n                <svg width="18" height="18" viewBox="0 0 23 23" fill="none">\n                    <path fill="#f35325" d="M1 1h10v10H1z"/>\n                    <path fill="#81bc06" d="M12 1h10v10H12z"/>\n                    <path fill="#05a6f0" d="M1 12h10v10H1z"/>\n                    <path fill="#ffba08" d="M12 12h10v10H12z"/>\n                </svg>\n                Sign in with Microsoft 365\n            </a>\n\n            <div style="margin-top: 24px; font-size: 0.75rem; color: var(--text-muted);">\n                Powered by Adroit AI • Production Ready\n            </div>\n        </div>\n    </div>\n</body>\n</html>\n'

